"""知识库诊断引擎（P6）—— 基于 rules.yaml 的仿真结果诊断。

激活 knowledge/rules.yaml 中的规则，对仿真结果进行自动诊断：
- 初值估计规则（initial_value）：给出参数初值建议
- 诊断规则（diagnosis）：分析异常指标，给出修复建议
"""

from __future__ import annotations

import logging
import re
from pathlib import Path
from typing import Any

import yaml

logger = logging.getLogger(__name__)

# 默认规则文件路径
_DEFAULT_RULES_PATH = Path(__file__).parent.parent.parent.parent / "knowledge" / "rules.yaml"


class DiagnosisEngine:
    """知识库诊断引擎。

    加载 rules.yaml 中的规则，对仿真结果进行自动诊断。
    """

    def __init__(self, rules_path: str | Path | None = None) -> None:
        self.rules_path = Path(rules_path) if rules_path else _DEFAULT_RULES_PATH
        self.rules: list[dict[str, Any]] = []
        self._load_rules()

    def _load_rules(self) -> None:
        """加载规则文件。"""
        if not self.rules_path.exists():
            logger.warning("规则文件不存在: %s", self.rules_path)
            return

        try:
            with open(self.rules_path, encoding="utf-8") as f:
                data = yaml.safe_load(f)
            self.rules = data.get("rules", [])
            logger.info("加载 %d 条诊断规则", len(self.rules))
        except Exception as e:
            logger.error("加载规则文件失败: %s", e)

    def diagnose(
        self,
        metrics: dict[str, float],
        model_name: str = "all",
        objectives: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        """对仿真结果进行诊断。"""
        diagnoses: list[dict[str, Any]] = []
        suggestions: list[str] = []
        initial_values: dict[str, Any] = {}

        for rule in self.rules:
            applicable = rule.get("applicable_models", [])
            if "all" not in applicable and model_name not in applicable:
                continue

            category = rule.get("category", "")

            if category == "diagnosis":
                diagnosis = self._check_diagnosis_rule(rule, metrics, objectives)
                if diagnosis:
                    diagnoses.append(diagnosis)
                    suggestions.append(diagnosis.get("hint", ""))

            elif category == "initial_value":
                initial_value = self._estimate_initial_value(rule, metrics)
                if initial_value:
                    initial_values.update(initial_value)

        return {
            "ok": True,
            "diagnoses": diagnoses,
            "suggestions": [s for s in suggestions if s],
            "initial_values": initial_values,
            "rules_applied": len(diagnoses) + len(initial_values),
        }

    def diagnose_divergence(self, config_a: Any, config_b: Any, **kwargs: Any) -> dict[str, Any]:
        """G12：跨引擎分歧诊断（薄委托，见模块级 diagnose_divergence）。"""
        return diagnose_divergence(config_a, config_b, **kwargs)

    def _check_diagnosis_rule(
        self,
        rule: dict[str, Any],
        metrics: dict[str, float],
        objectives: list[dict[str, Any]] | None,
    ) -> dict[str, Any] | None:
        """检查诊断规则是否触发。"""
        rule_id = rule.get("id", "")
        description = rule.get("description", "")
        hint = rule.get("hint", "")

        if rule_id == "R002":
            # 指标缺失时跳过而非按默认值判断（C5 修复：原先默认 0 > -10，
            # objectives 不含 s11_db 的配方会被误报 R002）
            s11 = metrics.get("s11_db_max_in_band")
            if s11 is not None and s11 > -10:
                return {
                    "rule_id": rule_id,
                    "description": description,
                    "hint": hint,
                    "severity": "warning",
                    "metric": "s11_db_max_in_band",
                    "value": s11,
                    "threshold": -10,
                }

        if rule_id == "R003":
            s21 = metrics.get("s21_db_mean_in_band")
            if s21 is not None and s21 < -6:
                return {
                    "rule_id": rule_id,
                    "description": description,
                    "hint": hint,
                    "severity": "warning",
                    "metric": "s21_db_mean_in_band",
                    "value": s21,
                    "threshold": -6,
                }

        if rule_id == "R004":
            passivity = metrics.get("passivity_ok", True)
            if not passivity:
                return {
                    "rule_id": rule_id,
                    "description": description,
                    "hint": hint,
                    "severity": "error",
                    "metric": "passivity_ok",
                    "value": False,
                }

        return None

    def _estimate_initial_value(
        self,
        rule: dict[str, Any],
        metrics: dict[str, float],
    ) -> dict[str, Any] | None:
        """根据规则估计参数初值。"""
        rule_id = rule.get("id", "")

        if rule_id == "R001":
            return {
                "arm_len_mm": {
                    "formula": rule.get("formula", ""),
                    "example": rule.get("example", ""),
                }
            }

        return None


_engine: DiagnosisEngine | None = None


def get_diagnosis_engine() -> DiagnosisEngine:
    """获取诊断引擎单例。"""
    global _engine
    if _engine is None:
        _engine = DiagnosisEngine()
    return _engine


def diagnose_results(
    metrics: dict[str, float],
    model_name: str = "all",
    objectives: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """便捷函数：对仿真结果进行诊断。"""
    engine = get_diagnosis_engine()
    return engine.diagnose(metrics, model_name, objectives)


# ---------------------------------------------------------------------------
# G12 跨引擎分歧诊断（continuation-plan §10.7 G12 / §10.22 #19）
# ---------------------------------------------------------------------------
# 与既有 rules 诊断（R001-R009）正交：本段不读 rules.yaml、不调用任何 LLM。
# 输入=两引擎配置与结果，输出=配置逐项 diff + 教训核对表 + 有序根因清单。
# LLM 只能消费本输出做解释，全部判定在确定性规则内（AGENTS 规则 7）。

CONFIG_DIMENSIONS: tuple[str, ...] = ("mesh", "port", "material", "boundary")

LESSON_SAME_NAME_INVERSE = "#154（同名参数跨适配器语义相反）"
LESSON_WAVE_PORT_SIZE = "#191（波端口尺寸不符官方口径）"
LESSON_VERIFY_MODEL_FIRST = "铁律 1c（先验模型/先对照官方例）"

CAUSE_MESH_LEVEL = "mesh_level_mismatch"
CAUSE_PORT_OFFICIAL = "port_size_official_deviation"
CAUSE_PORT_MISMATCH = "port_size_mismatch"
CAUSE_PARAM_INVERSE = "param_semantics_inverted"
CAUSE_MATERIAL = "material_mismatch"
CAUSE_BOUNDARY = "boundary_mismatch"
CAUSE_RESULT_TOLERANCE = "result_tolerance_exceeded"
CAUSE_MODEL_NOT_VERIFIED = "model_not_verified"

# 单位归一表（#121：跨适配器数值先统一单位再比较，禁止裸数值对拍）
_UNIT_SCALE: dict[str, tuple[str, float]] = {
    "m": ("length_mm", 1000.0),
    "mm": ("length_mm", 1.0),
    "cm": ("length_mm", 10.0),
    "um": ("length_mm", 1e-3),
    "hz": ("freq_ghz", 1e-9),
    "khz": ("freq_ghz", 1e-6),
    "mhz": ("freq_ghz", 1e-3),
    "ghz": ("freq_ghz", 1.0),
    "s": ("time_s", 1.0),
    "ms": ("time_s", 1e-3),
    "us": ("time_s", 1e-6),
    "ns": ("time_s", 1e-9),
    "ps": ("time_s", 1e-12),
    "deg": ("angle_deg", 1.0),
    "ohm": ("impedance_ohm", 1.0),
}

_QUANTITY_RE = re.compile(r"^\s*([-+]?[0-9]*\.?[0-9]+(?:[eE][-+]?[0-9]+)?)\s*([a-zA-Z]+)?\s*$")


def _parse_quantity(value: Any) -> tuple[float, str | None] | None:
    """把数值/带单位字符串归一为 (基准值, 单位族)；不可解析返回 None。

    基准：长度→mm、频率→GHz、时间→s、角度→deg、阻抗→Ω（#121）。
    """
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value), None
    if not isinstance(value, str):
        return None
    match = _QUANTITY_RE.match(value)
    if not match:
        return None
    try:
        num = float(match.group(1))
    except (TypeError, ValueError):
        return None
    unit = (match.group(2) or "").lower()
    if not unit:
        return num, None
    spec = _UNIT_SCALE.get(unit)
    if spec is None:
        return num, None  # 未知单位：不猜，按原值比较
    return num * spec[1], spec[0]


def _quantity_equal(qa: tuple[float, str | None], qb: tuple[float, str | None],
                    rel_tol: float, abs_tol: float) -> bool:
    """两个归一量化是否相等（不同单位族=不相等）。"""
    if qa[1] is not None and qb[1] is not None and qa[1] != qb[1]:
        return False
    va, vb = qa[0], qb[0]
    return abs(va - vb) <= abs_tol + rel_tol * max(abs(va), abs(vb))


def _flatten_config(obj: Any, prefix: str, out: dict[str, Any]) -> None:
    """把嵌套配置展平为 {路径: 叶值}（路径用 . 连接，sorted 保证确定性）。"""
    if isinstance(obj, dict):
        for key in sorted(obj, key=str):
            _flatten_config(obj[key], f"{prefix}.{key}" if prefix else str(key), out)
    else:
        out[prefix] = obj


def diff_engine_configs(
    config_a: Any,
    config_b: Any,
    *,
    dimensions: tuple[str, ...] = CONFIG_DIMENSIONS,
    rel_tol: float = 0.02,
    abs_tol: float = 1e-9,
) -> dict[str, Any]:
    """两引擎配置逐项 diff（网格/端口/材料/边界 + other 桶）。

    数值先按 _UNIT_SCALE 归一单位（#121），再以 rel_tol/abs_tol 判定是否分歧。
    返回 JSON 友好结构：{"dimensions": {dim: [entry, ...]}, "differing": [...],
    "n_differences": int}。entry.kind ∈ {only_in_a, only_in_b, value_changed,
    unit_kind_mismatch}。
    """
    a = config_a if isinstance(config_a, dict) else {}
    b = config_b if isinstance(config_b, dict) else {}
    scanned: list[tuple[str, Any, Any]] = []
    for dim in dimensions:
        scanned.append((dim, a.get(dim, {}), b.get(dim, {})))
    other_a = {k: v for k, v in a.items() if k not in dimensions}
    other_b = {k: v for k, v in b.items() if k not in dimensions}
    scanned.append(("other", other_a, other_b))

    out_dims: dict[str, list[dict[str, Any]]] = {}
    for dim, sub_a, sub_b in scanned:
        flat_a: dict[str, Any] = {}
        flat_b: dict[str, Any] = {}
        _flatten_config(sub_a, "", flat_a)
        _flatten_config(sub_b, "", flat_b)
        entries: list[dict[str, Any]] = []
        for path in sorted(set(flat_a) | set(flat_b)):
            full = f"{dim}.{path}" if path else dim
            if path not in flat_a:
                entries.append({"path": full, "a": None, "b": flat_b[path], "kind": "only_in_b"})
                continue
            if path not in flat_b:
                entries.append({"path": full, "a": flat_a[path], "b": None, "kind": "only_in_a"})
                continue
            va, vb = flat_a[path], flat_b[path]
            qa, qb = _parse_quantity(va), _parse_quantity(vb)
            if qa is not None and qb is not None:
                if not _quantity_equal(qa, qb, rel_tol, abs_tol):
                    kind = ("unit_kind_mismatch"
                            if qa[1] is not None and qb[1] is not None and qa[1] != qb[1]
                            else "value_changed")
                    rel = abs(qa[0] - qb[0]) / max(abs(qa[0]), abs(qb[0]), abs_tol)
                    entries.append({
                        "path": full, "a": va, "b": vb, "kind": kind,
                        "normalized_a": qa[0], "normalized_b": qb[0], "rel_delta": rel,
                    })
                continue
            if va != vb:
                entries.append({"path": full, "a": va, "b": vb, "kind": "value_changed"})
        out_dims[dim] = entries

    return {
        "dimensions": out_dims,
        "differing": [d for d, e in out_dims.items() if e],
        "n_differences": sum(len(e) for e in out_dims.values()),
    }


def _diff_results(result_a: Any, result_b: Any, tolerance: Any) -> dict[str, Any]:
    """两引擎结果指标 diff（共享键 + 容差；容差可为标量或 {metric: tol}）。"""
    if not isinstance(result_a, dict) or not isinstance(result_b, dict):
        return {"diverged": False, "entries": [], "note": "结果缺失，仅按配置分歧诊断"}
    entries: list[dict[str, Any]] = []
    for key in sorted(set(result_a) & set(result_b)):
        va, vb = result_a[key], result_b[key]
        num_a, num_b = None, None
        if not isinstance(va, bool) and not isinstance(vb, bool):
            try:
                num_a, num_b = float(va), float(vb)
            except (TypeError, ValueError):
                num_a, num_b = None, None
        if num_a is None or num_b is None:
            if va != vb:
                entries.append({"metric": key, "a": va, "b": vb, "kind": "value_changed"})
            continue
        tol = tolerance.get(key, 0.5) if isinstance(tolerance, dict) else float(tolerance)
        delta = abs(num_a - num_b)
        if delta != delta:  # NaN：不可判定，跳过（不误报）
            continue
        if delta > tol:
            entries.append({
                "metric": key, "a": num_a, "b": num_b,
                "delta": delta, "tolerance": tol, "kind": "beyond_tolerance",
            })
    return {"diverged": bool(entries), "entries": entries, "note": ""}


def _frequency_shift(results_diff: dict[str, Any]) -> bool:
    """结果 diff 中频率类指标相对偏移 >1% → 疑网格档/建模分歧。"""
    for entry in results_diff.get("entries", []):
        key = str(entry.get("metric", "")).lower()
        if not any(token in key for token in ("f0", "freq", "ghz")):
            continue
        a, b = entry.get("a"), entry.get("b")
        if (isinstance(a, (int, float)) and isinstance(b, (int, float)) and a
                and abs(b - a) / abs(a) > 0.01):
            return True
    return False


def _extract_semantics(config: Any) -> dict[str, str]:
    """取配置里的参数语义声明（param_semantics / semantics）。"""
    if not isinstance(config, dict):
        return {}
    for key in ("param_semantics", "semantics"):
        value = config.get(key)
        if isinstance(value, dict):
            return {str(k): str(v) for k, v in value.items()}
    return {}


def _detect_param_semantics(
    config_a: Any,
    config_b: Any,
    semantics_a: Any,
    semantics_b: Any,
    config_diff: dict[str, Any],
) -> dict[str, Any] | None:
    """#154：同名参数跨适配器语义相反（声明角色冲突或数值互反/取负）。"""
    sa = semantics_a if isinstance(semantics_a, dict) else _extract_semantics(config_a)
    sb = semantics_b if isinstance(semantics_b, dict) else _extract_semantics(config_b)
    sa = {str(k): str(v) for k, v in sa.items()}
    sb = {str(k): str(v) for k, v in sb.items()}
    flips = [
        {"param": name, "role_a": sa[name], "role_b": sb[name]}
        for name in sorted(set(sa) & set(sb)) if sa[name] != sb[name]
    ]
    inversions: list[dict[str, Any]] = []
    for entries in config_diff["dimensions"].values():
        for entry in entries:
            if entry.get("kind") != "value_changed":
                continue
            qa = _parse_quantity(entry.get("a"))
            qb = _parse_quantity(entry.get("b"))
            if qa is None or qb is None:
                continue
            va, vb = qa[0], qb[0]
            if va == 0 or vb == 0:
                continue
            if abs(va * vb - 1.0) <= 1e-6 and abs(va - 1.0) > 1e-9:
                inversions.append({"path": entry["path"], "kind": "reciprocal",
                                   "a": entry.get("a"), "b": entry.get("b")})
            elif abs(va + vb) <= 1e-9:
                inversions.append({"path": entry["path"], "kind": "negated",
                                   "a": entry.get("a"), "b": entry.get("b")})
    if not flips and not inversions:
        return None
    n = len(flips) + len(inversions)
    role_pairs = "；".join(f"{f['param']}: {f['role_a']} vs {f['role_b']}" for f in flips)
    inv_pairs = "；".join(f"{i['path']}（{i['kind']}）" for i in inversions)
    detail = "#154 同名参数跨适配器语义相反"
    if role_pairs:
        detail += f"：{role_pairs}"
    if inv_pairs:
        detail += f"；数值互反/取负：{inv_pairs}"
    return {
        "id": CAUSE_PARAM_INVERSE,
        "root_cause": "同名参数跨适配器语义相反（或数值互反/取负）",
        "lesson_ref": LESSON_SAME_NAME_INVERSE,
        "severity": "error",
        "score": 3.0 + 0.2 * max(0, n - 1),
        "detail": detail,
        "evidence": {"role_flips": flips, "numeric_inversions": inversions},
        "actions": [
            "逐参数对语义（走 core/physics_roles 的角色表），禁止各适配器按同名参数自行解释（#154）",
            "把两侧参数映射写进配置/清单后重跑对照，勿在校准层补偿语义错配",
        ],
    }


def _detect_port(
    config_a: Any,
    config_b: Any,
    config_diff: dict[str, Any],
    official: Any,
) -> dict[str, Any] | None:
    """#191：波端口尺寸不符官方口径（有官参时按官参判，否则仅报两侧不一致）。"""
    entries = config_diff["dimensions"].get("port", [])
    if not entries:
        return None
    official_port: dict[str, Any] = {}
    if isinstance(official, dict):
        inner = official.get("port")
        official_port = inner if isinstance(inner, dict) else official
    official_flat: dict[str, Any] = {}
    _flatten_config(official_port, "", official_flat)
    deviations: list[dict[str, Any]] = []
    if official_flat:
        flat_a: dict[str, Any] = {}
        flat_b: dict[str, Any] = {}
        _flatten_config(config_a.get("port", {}) if isinstance(config_a, dict) else {}, "", flat_a)
        _flatten_config(config_b.get("port", {}) if isinstance(config_b, dict) else {}, "", flat_b)
        for path, ref in sorted(official_flat.items()):
            qr = _parse_quantity(ref)
            if qr is None:
                continue
            for side, table in (("a", flat_a), ("b", flat_b)):
                if path not in table:
                    continue
                qv = _parse_quantity(table[path])
                if qv is None:
                    continue
                if not _quantity_equal(qv, qr, 1e-6, 1e-9):
                    deviations.append({"side": side, "path": f"port.{path}",
                                       "value": table[path], "official": ref})
    if deviations:
        detail = "#191 波端口尺寸偏离官方口径：" + "；".join(
            f"{d['side']} 侧 {d['path']}={d['value']}（官方 {d['official']}）" for d in deviations)
        return {
            "id": CAUSE_PORT_OFFICIAL,
            "root_cause": "波端口尺寸不符官方口径（#191）",
            "lesson_ref": LESSON_WAVE_PORT_SIZE,
            "severity": "error",
            "score": 3.0,
            "detail": detail,
            "evidence": {"official_port": official_port, "deviations": deviations,
                         "port_diff": entries},
            "actions": [
                "按官方口径重设波端口尺寸（#191：Ansys Help 波端口尺寸惯例，勿凭经验拍数）",
                "HFSS 异常先查官方文档核对端口面尺寸/参考面（AGENTS 硬规则），再对齐另一引擎",
                "对齐后重跑两引擎对照；勿在校准层补偿端口口径错误",
            ],
        }
    return {
        "id": CAUSE_PORT_MISMATCH,
        "root_cause": "端口配置存在差异（无官方口径参照或双方均符官方）",
        "lesson_ref": "#191（波端口尺寸口径；本次未检出偏离官参）",
        "severity": "warning",
        "score": 1.2,
        "detail": "两引擎端口配置不一致：" + "；".join(
            f"{e['path']}: {e.get('a')!r} vs {e.get('b')!r}" for e in entries),
        "evidence": {"port_diff": entries, "official_port": official_port},
        "actions": [
            "核对端口类型/尺寸/参考面是否同口径（#191）",
            "补一份官方口径参照后再判定是否偏离（当前只能判两侧不一致）",
        ],
    }


def _detect_mesh(config_diff: dict[str, Any], results_diff: dict[str, Any]) -> dict[str, Any] | None:
    """网格档分歧（#152/#219）：档位/单元数/自适应设置不同，会淹没物理分歧。"""
    entries = config_diff["dimensions"].get("mesh", [])
    if not entries:
        return None
    score = min(2.5, 1.5 + 0.25 * max(0, len(entries) - 1))
    shifted = _frequency_shift(results_diff)
    if shifted:
        score += 0.5
    detail = "两引擎网格档不一致：" + "；".join(
        f"{e['path']}: {e.get('a')!r} vs {e.get('b')!r}" for e in entries)
    if shifted:
        detail += "；结果频率类指标相对偏移 >1%（疑网格伪象/建模分歧）"
    return {
        "id": CAUSE_MESH_LEVEL,
        "root_cause": "两引擎网格档不一致（网格伪象/收敛档不同，#152/#219）",
        "lesson_ref": "#152/#219（网格最小间距守卫、网格细化中心漂移）",
        "severity": "warning",
        "score": score,
        "detail": detail,
        "evidence": {"mesh_diff": entries, "frequency_shift": shifted},
        "actions": [
            "统一两引擎网格口径（base/自适应/每波长单元数）后再比较结果",
            "做网格收敛研究（≥2 档）：中心随细化单调上移=伪象自证（#219②）",
            "以 HFSS 为对齐基准仲裁网格分歧归属（AGENTS 硬规则）",
        ],
    }


def _detect_dimension(
    config_diff: dict[str, Any], dim: str, cause: str, root_cause: str,
    lesson: str, base: float,
) -> dict[str, Any] | None:
    """通用维度分歧候选（材料/边界）。"""
    entries = config_diff["dimensions"].get(dim, [])
    if not entries:
        return None
    return {
        "id": cause,
        "root_cause": root_cause,
        "lesson_ref": lesson,
        "severity": "warning",
        "score": base + 0.1 * max(0, len(entries) - 1),
        "detail": f"两引擎 {dim} 配置不一致：" + "；".join(
            f"{e['path']}: {e.get('a')!r} vs {e.get('b')!r}" for e in entries),
        "evidence": {f"{dim}_diff": entries},
        "actions": [
            f"逐项核对 {dim} 配置是否同源（#121：先统一单位再比较）",
            "模型不一致时禁止进入校准（铁律 1b：先验模型）",
        ],
    }


def diagnose_divergence(
    config_a: Any,
    config_b: Any,
    *,
    result_a: dict[str, Any] | None = None,
    result_b: dict[str, Any] | None = None,
    engine_a: str = "engine_a",
    engine_b: str = "engine_b",
    official: Any = None,
    semantics_a: Any = None,
    semantics_b: Any = None,
    result_tolerance: Any = 0.5,
    config_rel_tol: float = 0.02,
    config_abs_tol: float = 1e-9,
    provenance: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """G12：跨引擎分歧诊断（配置逐项 diff + 教训核对表 + 有序根因清单）。

    参数：
        config_a / config_b: 两引擎配置 dict（含 mesh/port/material/boundary
            子配置；可带 param_semantics 声明）。数值可带单位（mm/GHz/s...）。
        result_a / result_b: 两引擎结果指标 dict（如 f0_ghz/s11_db_min）。
        official: 官方口径参照配置（如 {"port": {...}}），用于 #191 偏离判定。
        semantics_a / semantics_b: 参数语义声明 {param: role}（覆盖 config 内声明）。
        result_tolerance: 结果容差（标量或 {metric: tol}）。
        config_rel_tol / config_abs_tol: 配置数值比较容差。
        provenance: 可选来源说明，原样带回。

    返回（JSON 友好，排序后的诊断清单，top_causes 为 top-2 命中口径）::

        {"ok", "diverged", "results_diverged", "config_diverged",
         "config_diff", "result_diff", "diagnoses", "top_causes",
         "checklist", "suggestions", "llm_role"}

    本函数不做任何 LLM 调用；LLM 仅可消费本输出做解释（llm_role="explain-only"）。
    """
    config_diff = diff_engine_configs(
        config_a, config_b, rel_tol=config_rel_tol, abs_tol=config_abs_tol)
    results_diff = _diff_results(result_a, result_b, result_tolerance)
    config_diverged = config_diff["n_differences"] > 0
    results_diverged = bool(results_diff.get("diverged"))

    candidates: list[dict[str, Any]] = []
    semantics_cand = _detect_param_semantics(
        config_a, config_b, semantics_a, semantics_b, config_diff)
    if semantics_cand:
        candidates.append(semantics_cand)
    port_cand = _detect_port(config_a, config_b, config_diff, official)
    if port_cand:
        candidates.append(port_cand)
    mesh_cand = _detect_mesh(config_diff, results_diff)
    if mesh_cand:
        candidates.append(mesh_cand)
    material_cand = _detect_dimension(
        config_diff, "material", CAUSE_MATERIAL,
        "两引擎材料参数不一致", "材料铁律（#121 单位归一 + 1b 先验模型）", 1.3)
    if material_cand:
        candidates.append(material_cand)
    boundary_cand = _detect_dimension(
        config_diff, "boundary", CAUSE_BOUNDARY,
        "两引擎边界条件不一致", "边界/PML 口径（#154 前节）", 1.1)
    if boundary_cand:
        candidates.append(boundary_cand)

    lesson154 = any(c["id"] == CAUSE_PARAM_INVERSE for c in candidates)
    lesson191 = any(c["id"] == CAUSE_PORT_OFFICIAL for c in candidates)

    if results_diverged:
        candidates.append({
            "id": CAUSE_RESULT_TOLERANCE,
            "root_cause": "两引擎结果超容差（未见已知配置指纹）",
            "lesson_ref": "容差对照（结果面）",
            "severity": "warning",
            "score": 0.5,
            "detail": "结果指标超容差：" + "；".join(
                f"{e['metric']}: {e.get('a')} vs {e.get('b')}"
                f"（Δ={e.get('delta')}，容差 {e.get('tolerance')}）"
                for e in results_diff.get("entries", [])),
            "evidence": {"result_diff": results_diff.get("entries", [])},
            "actions": [
                "结果超容差但无已知配置指纹：先人工审计建模（铁律 1c），勿直接调参",
            ],
        })

    model_verify_hit = config_diverged and not (lesson154 or lesson191)
    if model_verify_hit:
        candidates.append({
            "id": CAUSE_MODEL_NOT_VERIFIED,
            "root_cause": "配置存在一般性分歧：先验模型/先对照官方例",
            "lesson_ref": LESSON_VERIFY_MODEL_FIRST,
            "severity": "info",
            "score": 0.3,
            "detail": "配置分歧未命中 #154/#191 已知签名，按铁律 1c 先做建模审计",
            "evidence": {"differing_dimensions": config_diff["differing"]},
            "actions": [
                "先验模型再校准：逐行审计渲染脚本/几何拓扑/端口约定/单位（铁律 1b/1c）",
                "对照 docs/rf_template_references.md 官方例口径，确认模型正确后再比较差异",
            ],
        })

    candidates.sort(key=lambda c: -c["score"])
    top_causes = [c["id"] for c in candidates[:2]]

    checklist = [
        {
            "lesson": LESSON_SAME_NAME_INVERSE,
            "hit": lesson154,
            "evidence": "已检出同名参数语义反转" if lesson154 else "未检出同名参数语义反转",
        },
        {
            "lesson": LESSON_WAVE_PORT_SIZE,
            "hit": lesson191,
            "evidence": ("已检出波端口尺寸偏离官方口径" if lesson191
                         else "未检出波端口尺寸偏离官方口径"),
        },
        {
            "lesson": LESSON_VERIFY_MODEL_FIRST,
            "hit": model_verify_hit,
            "evidence": ("配置有分歧且未命中 #154/#191：须先验模型/对照官方例"
                         if model_verify_hit else "已由具体教训解释，无需泛化归因"),
        },
    ]

    suggestions: list[str] = []
    for cand in candidates[:2]:
        for action in cand["actions"]:
            if action not in suggestions:
                suggestions.append(action)

    report: dict[str, Any] = {
        "ok": True,
        "diverged": results_diverged or config_diverged,
        "results_diverged": results_diverged,
        "config_diverged": config_diverged,
        "engine_a": engine_a,
        "engine_b": engine_b,
        "config_diff": config_diff,
        "result_diff": results_diff,
        "diagnoses": candidates,
        "top_causes": top_causes,
        "checklist": checklist,
        "suggestions": suggestions,
        "llm_role": "explain-only",
    }
    if provenance is not None:
        report["provenance"] = provenance
    return report

files.src/rfauto/infra/version_probe.py:
"""EDA 版本探测（项目 B / 项目 A 共用基础设施）。

职责：
- 枚举本机 AEDT 安装（ANSYSEM_ROOTxxx 环境变量 + 注册表），解析版本号
- 解析 ADS 安装版本（目录名 ADS<yyyy>）
- 从 knowledge/compat_matrix.yaml 读取版本支持等级（verified / best_effort / unsupported）

背景（TODO 项目 B）：原先 aedt_version 由"路径含 v231"字符串启发式推导，
脆弱且只认两个硬编码版本（经验 10：EDA 默认值不可信）。本模块把探测
收敛到 infra 层，service/optimization 只调用 resolve 函数。
"""

from __future__ import annotations

import os
import re
from pathlib import Path
from typing import Any

import yaml

# 仓库根目录下的兼容矩阵（源码布局；wheel 安装不支持，与 diagnosis.rules.yaml 一致）
_COMPAT_MATRIX_PATH = Path(__file__).parent.parent.parent.parent / "knowledge" / "compat_matrix.yaml"

_ANSYSEM_ENV_RE = re.compile(r"^ANSYSEM_ROOT(\d+)$")
_AEDT_DIR_RE = re.compile(r"^[vV]?(\d{3,4})$")
# ADS 安装目录名：4 位年份（ADS2027）或 2 位短年（ADS27，2026-09-18 现役安装
# E:/ADS/ADS27 实测目录名，rm-ads-wp43 治理），短年统一归一到 20xx。
_ADS_DIR_RE = re.compile(r"ADS(\d{4}|\d{2})$", re.IGNORECASE)

_DEFAULT_AEDT_VERSION = "2024.1"  # pyaedt 未指定版本时的默认值


def build_to_aedt_version(build_num: int) -> str:
    """ANSYS 内部版本号 → 年.发布 版本串。

    规则：231 → 2023 R1 → "2023.1"；251 → 2025 R1；262 → 2026 R2。
    """
    year = 2000 + build_num // 10
    release = build_num % 10
    return f"{year}.{release}"


def detect_aedt_versions() -> list[dict[str, Any]]:
    """枚举本机 AEDT 安装。

    来源（按可信度）：
    1. ANSYSEM_ROOT<build> 环境变量（AEDT 安装时写入，指向 <版本目录>\\Win64）
    2. Windows 注册表 HKLM\\SOFTWARE\\ANSYS, Inc.（best-effort，非 Windows/无权限时跳过）

    Returns:
        [{"version_id": "v231", "path": Path, "aedt_version": "2023.1",
          "source": "env"}...] 按版本新→旧排序，重复路径去重。
    """
    installs: dict[str, dict[str, Any]] = {}

    for name, value in os.environ.items():
        m = _ANSYSEM_ENV_RE.match(name)
        if not m:
            continue
        build = int(m.group(1))
        root = Path(value)
        # ANSYSEM_ROOT231 = <版本目录>\Win64 → 版本目录取上一层
        # ANSYSEM_ROOT261 = <版本目录>\AnsysEM → 版本目录取上一层
        version_dir = root.parent if root.name.lower() in ("win64", "ansysem") else root
        version_id = f"v{build}"
        installs[str(version_dir)] = {
            "version_id": version_id,
            "path": version_dir,
            "aedt_version": build_to_aedt_version(build),
            "source": f"env:{name}",
        }

    # 注册表兜底（环境变量缺失时仍可能发现安装）
    if not installs:
        installs.update(_detect_from_registry())

    result = sorted(installs.values(), key=lambda e: e["aedt_version"], reverse=True)
    # 只保留真实存在的路径
    return [e for e in result if e["path"].exists()]


def _detect_from_registry() -> dict[str, dict[str, Any]]:
    """Windows 注册表探测（best-effort，任何失败静默返回空）。"""
    result: dict[str, dict[str, Any]] = {}
    try:  # pragma: no cover - 需要 Windows 真机
        import winreg

        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\ANSYS, Inc.") as key:
            i = 0
            while True:
                try:
                    subkey_name = winreg.EnumKey(key, i)
                    i += 1
                except OSError:
                    break
                m = re.match(r"^[vV]?(\d{3,4})(?:\.(\d))?$", subkey_name)
                if not m:
                    continue
                build = int(m.group(1))
                try:
                    with winreg.OpenKey(key, subkey_name) as sk:
                        install_dir, _ = winreg.QueryValueEx(sk, "InstallDir")
                except OSError:
                    continue
                p = Path(str(install_dir))
                version_dir = p.parent if p.name.lower() == "win64" else p
                result[str(version_dir)] = {
                    "version_id": f"v{build}",
                    "path": version_dir,
                    "aedt_version": build_to_aedt_version(build),
                    "source": "registry",
                }
    except Exception:
        return result
    return result


def resolve_aedt_install(explicit_path: str | Path | None = None) -> dict[str, Any] | None:
    """解析实际使用的 AEDT 安装（显式路径优先，否则自动探测最高版本）。

    优先级：
    1. explicit_path（RFAUTO_AEDT_PATH）：存在即用；版本号优先从目录名
       （vNNN）解析，解析不出时按路径前缀匹配已探测安装，再不行回退默认值
    2. 自动探测取最高版本（项目 B 验收：无环境变量也能发现本机 AEDT）

    Returns:
        {"path": Path, "aedt_version": str, "source": str} 或 None（未找到）
    """
    if explicit_path:
        p = Path(explicit_path)
        if p.exists():
            m = _AEDT_DIR_RE.match(p.name)
            if m:
                return {
                    "path": p,
                    "aedt_version": build_to_aedt_version(int(m.group(1))),
                    "source": "explicit",
                }
            # 目录名不含 vNNN：尝试用探测结果做路径前缀匹配
            for inst in detect_aedt_versions():
                try:
                    if p.resolve() == inst["path"].resolve() or p.resolve() in inst["path"].resolve().parents:
                        return dict(inst, source="explicit+probe")
                except OSError:
                    continue
            return {"path": p, "aedt_version": _DEFAULT_AEDT_VERSION, "source": "explicit-default"}
        return None

    detected = detect_aedt_versions()
    if detected:
        best = detected[0]
        return {"path": best["path"], "aedt_version": best["aedt_version"], "source": "auto-probe"}
    return None


def detect_ads_version(ads_dir: str | Path | None = None) -> str | None:
    """从 ADS 安装目录名解析版本（...\\ADS2027 或 ...\\ADS27 → "2027"）。解析不出返回 None。"""
    if ads_dir is None:
        from rfauto.infra.config import load_settings

        ads_dir = load_settings().hpeesof_dir or None
        if ads_dir is None:
            return None
    m = _ADS_DIR_RE.search(str(Path(ads_dir).name))
    if not m:
        return None
    digits = m.group(1)
    return digits if len(digits) == 4 else f"20{digits}"


# ---------------------------------------------------------------------------
# 兼容矩阵
# ---------------------------------------------------------------------------

def load_compat_matrix() -> dict[str, Any]:
    """读取 knowledge/compat_matrix.yaml；缺失/损坏时返回空矩阵（不抛异常）。"""
    if not _COMPAT_MATRIX_PATH.exists():
        return {}
    try:
        with open(_COMPAT_MATRIX_PATH, encoding="utf-8") as f:
            data = yaml.safe_load(f) or {}
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


_LEVELS = ("verified", "best_effort", "unsupported")


def compat_level(tool: str, version: str) -> str:
    """查版本支持等级：tool ∈ {"aedt", "ads"}。

    匹配优先级：精确版本 → default_level → "unsupported"（矩阵缺失时按
    best_effort 处理，即"能用但不背书"——保守但不阻塞）。
    """
    matrix = load_compat_matrix()
    tool_cfg = matrix.get(tool, {})
    versions = tool_cfg.get("versions", {}) if isinstance(tool_cfg, dict) else {}
    entry = versions.get(version)
    if entry is not None:
        if isinstance(entry, dict):
            return str(entry.get("level", tool_cfg.get("default_level", "best_effort")))
        return str(entry)
    return str(tool_cfg.get("default_level", "best_effort"))

files.src/rfauto/optimization/model_registry.p:
"""代理模型资产注册表内核（RB-ML-1，sa_specs2 §六）。

与 ``optimization/surrogate/base.py`` 的 ``SurrogateRegistry``（类工厂注册
表：kind → 可实例化模型类）**正交**：本件管理**训练产物资产**——版本/
血缘/champion-challenger/漂移失效四件事（MLflow Model Registry 模式参照，
非依赖引入——负结果台账已裁）。

存储形态（spec §6.2-1）：
- 元数据：``knowledge/surrogate_registry.yaml``（tracked；缺省相对 cwd，
  路径可注入）；
- 模型 blob：``runs/.model_store/<sha256>.pkl``（gitignored 内容寻址，
  dag_cache file_sha256 同法；pickle 仅消费本仓产物——spec §6.4 风险面，
  反序列化前强制 sha256 复核）；
- 键：``{template_family, channel, feature_set_fingerprint}``——指纹=
  特征名+顺序+预处理的 sha256 前 16（RB-ML-3 特征快照共键，未来件）；
  读取面按指纹**精确匹配**，不模糊复用（schema 演进=旧键自然失配）。

并发与原子性（spec §6.3-4）：
- 版本号=键内 max+1，分配在文件锁（O_EXCL 重试+陈旧锁接管）+进程内
  RLock 双层之下；
- YAML 写=临时文件+``os.replace`` 原子替换（dag_cache 同法，Windows 安全）。

best-effort 边界（#105）：本内核的调用方（service 面/surrogate_loop 收尾
钩子）负责 try 包裹——注册失败不阻塞战役；内核自身对可预期坏输入返回
``{"ok": False, "reason": ...}`` 而不抛（blob 损坏/缺失/键缺失类）。

数值纪律（铁律 7）：本件不产生物理数字——heldout 误差由确定性代理模型
（surrogate_registry 既有内核）对留出样本预测后与实测 cost 差值得出；
champion 预测点同理（service 面消费）。
"""

from __future__ import annotations

import contextlib
import hashlib
import json
import os
import pickle
import subprocess
import threading
import time
from copy import deepcopy
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

__all__ = [
    "FINGERPRINT_LEN",
    "KEY_FIELDS",
    "REGISTRY_SCHEMA_VERSION",
    "STATUS_CHALLENGER",
    "STATUS_CHAMPION",
    "STATUS_RETIRED",
    "ModelRegistry",
    "canonical_key",
    "current_git_sha",
    "default_model_store_dir",
    "default_registry_path",
    "feature_set_fingerprint",
    "heldout_linf",
    "key_sort_id",
    "registry_write_enabled",
    "upsert_from_surrogate_loop",
]

REGISTRY_SCHEMA_VERSION = 1
STATUS_CHAMPION = "champion"
STATUS_CHALLENGER = "challenger"
STATUS_RETIRED = "retired"

#: 注册键字段（spec §6.2-1 schema；顺序即 canonical json 序）。
KEY_FIELDS: tuple[str, ...] = (
    "template_family", "channel", "feature_set_fingerprint")
FINGERPRINT_LEN = 16

LOCK_TIMEOUT_S = 10.0     #: 文件锁获取上限（超时抛 TimeoutError，不静默）
LOCK_STALE_S = 120.0      #: 陈旧锁接管阈值（持有者崩溃残留）
_BLOB_EXT = ".pkl"

_TRUE_STRINGS = frozenset({"1", "true", "yes", "on"})


def default_registry_path() -> Path:
    """注册表元数据缺省路径（相对 cwd；spec §6.2-1）。"""
    return Path("knowledge") / "surrogate_registry.yaml"


def default_model_store_dir() -> Path:
    """模型 blob 缺省落点（runs/ 已整体 gitignore）。"""
    return Path("runs") / ".model_store"


def feature_set_fingerprint(
    feature_names: list[str],
    preprocessing: dict[str, Any] | None = None,
) -> str:
    """特征集指纹：特征名+顺序+预处理 → sha256 前 16（spec §6.2-1）。

    canonical json（sort_keys）保证同内容同指纹；顺序敏感（列表序原样
    进哈希）——特征重排=新键，读取面自然失配不模糊复用。
    """
    payload = json.dumps(
        {"features": [str(n) for n in feature_names],
         "preprocessing": dict(preprocessing or {})},
        sort_keys=True, ensure_ascii=False,
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()[:FINGERPRINT_LEN]


def canonical_key(
    template_family: str, channel: str, feature_set_fingerprint: str,
) -> dict[str, str]:
    """构造注册键（三字段全必填，空串显式拒绝——键含糊即血缘断）。"""
    key = {
        "template_family": str(template_family),
        "channel": str(channel),
        "feature_set_fingerprint": str(feature_set_fingerprint),
    }
    missing = [f for f in KEY_FIELDS if not key[f]]
    if missing:
        raise ValueError(f"注册键字段不得为空: {missing}")
    return key


def key_sort_id(key: dict[str, Any]) -> str:
    """键的 canonical json 串（entries 排序/查找单源）。"""
    return json.dumps({f: str(key.get(f) or "") for f in KEY_FIELDS},
                      sort_keys=True, ensure_ascii=False)


def utc_now_iso() -> str:
    """UTC ISO 时间戳（created_at 字段单源）。"""
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def current_git_sha(cwd: str | Path | None = None) -> str | None:
    """当前 git HEAD sha（best-effort #105：任何失败返回 None 不抛）。"""
    try:
        out = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=str(cwd or Path.cwd()),
            capture_output=True, text=True, timeout=10, check=True,
        )
        sha = out.stdout.strip()
        return sha or None
    except Exception:  # 观测性 best-effort（#105）
        return None


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: str | Path, buf_size: int = 1 << 20) -> str:
    """文件 sha256（blob 完整性复核单源，lake_service._sha256_file 同法）。"""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while chunk := f.read(buf_size):
            h.update(chunk)
    return h.hexdigest()


def registry_write_enabled(environ: dict[str, str] | None = None) -> bool:
    """训练写点环境门（缺省关=旧环境行为逐字节不变，spec §6.3-6）。"""
    env = os.environ if environ is None else environ
    return str(env.get("RFAUTO_SURROGATE_REGISTRY_WRITE", "")).strip().lower() \
        in _TRUE_STRINGS


# ─── 注册表存储 ───────────────────────────────────────────────────────────────


class ModelRegistry:
    """训练产物注册表（YAML 元数据 + 内容寻址 blob，路径可注入）。"""

    def __init__(
        self,
        registry_path: str | Path | None = None,
        store_dir: str | Path | None = None,
    ) -> None:
        self.registry_path = Path(
            registry_path) if registry_path else default_registry_path()
        self.store_dir = Path(
            store_dir) if store_dir else default_model_store_dir()
        self._rlock = threading.RLock()

    # ── 读写基元 ─────────────────────────────────────────────────────────────

    def load(self) -> dict[str, Any]:
        """读注册表文档；文件不存在=空注册表（spec §6.3-6 零退化）。

        文件存在但 YAML 非法/顶层结构不对 → ValueError（坏账不静默吞，
        消费面自行 try 包裹决定降级姿势）。
        """
        import yaml

        if not self.registry_path.exists():
            return {"schema_version": REGISTRY_SCHEMA_VERSION, "entries": []}
        try:
            with open(self.registry_path, encoding="utf-8") as f:
                doc = yaml.safe_load(f)
        except yaml.YAMLError as exc:
            raise ValueError(
                f"注册表 YAML 解析失败（坏账不静默吞）: {exc}") from exc
        if doc is None:
            return {"schema_version": REGISTRY_SCHEMA_VERSION, "entries": []}
        if not isinstance(doc, dict) or not isinstance(
                doc.get("entries"), list):
            raise ValueError(
                f"注册表文件结构非法（entries 须为列表）: {self.registry_path}")
        return doc

    def _save(self, doc: dict[str, Any]) -> None:
        """原子写（tmp + os.replace；调用方须已持锁）。"""
        import yaml

        self.registry_path.parent.mkdir(parents=True, exist_ok=True)
        tmp = self.registry_path.with_suffix(
            self.registry_path.suffix + f".tmp{os.getpid()}")
        with open(tmp, "w", encoding="utf-8") as f:
            yaml.safe_dump(doc, f, allow_unicode=True, sort_keys=False)
        os.replace(tmp, self.registry_path)

    def _entries(self, doc: dict[str, Any]) -> list[dict[str, Any]]:
        return doc.setdefault("entries", [])

    @staticmethod
    def _find_entry(doc: dict[str, Any], key: dict[str, Any]) -> dict | None:
        kid = key_sort_id(key)
        for entry in doc.get("entries") or []:
            if key_sort_id(entry.get("key") or {}) == kid:
                return entry
        return None

    @contextlib.contextmanager
    def _locked(self):
        """互斥上下文：进程内 RLock + 跨进程 O_EXCL 锁文件（陈旧可接管）。

        锁文件落 store_dir（gitignored），名含注册表文件名防多注册表互踩。
        """
        with self._rlock:
            self.store_dir.mkdir(parents=True, exist_ok=True)
            lock_path = self.store_dir / (self.registry_path.name + ".lock")
            deadline = time.monotonic() + LOCK_TIMEOUT_S
            acquired = False
            fd = None
            while True:
                try:
                    fd = os.open(
                        lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
                    os.write(fd, str(os.getpid()).encode())
                    acquired = True
                    break
                except FileExistsError:
                    try:
                        age = time.time() - lock_path.stat().st_mtime
                    except FileNotFoundError:
                        continue
                    if age > LOCK_STALE_S:
                        # 陈旧锁接管（持有者崩溃残留）；Windows 下活进程
                        # 占用期 unlink 失败→按未过期处理走超时路径
                        try:
                            lock_path.unlink()
                        except OSError:
                            pass
                        else:
                            continue
                    if time.monotonic() > deadline:
                        raise TimeoutError(
                            f"注册表锁获取超时: {lock_path}") from None
                    time.sleep(0.02)
            try:
                yield
            finally:
                if acquired:
                    with contextlib.suppress(FileNotFoundError):
                        if fd is not None:
                            os.close(fd)
                        lock_path.unlink()

    # ── blob 面 ──────────────────────────────────────────────────────────────

    def _store_blob(self, data: bytes) -> tuple[str, str]:
        """内容寻址落 blob：返回 (sha256, 展示路径 posix 串)。"""
        self.store_dir.mkdir(parents=True, exist_ok=True)
        sha = sha256_bytes(data)
        blob = self.store_dir / f"{sha}{_BLOB_EXT}"
        if not blob.exists():
            tmp = blob.with_suffix(blob.suffix + f".tmp{os.getpid()}")
            with open(tmp, "wb") as f:
                f.write(data)
            os.replace(tmp, blob)
        return sha, self._display_path(blob)

    @staticmethod
    def _display_path(path: Path) -> str:
        """展示路径：cwd 下给相对 posix 串，否则绝对 posix（spec 示例形态）。"""
        p = Path(path)
        try:
            return p.resolve().relative_to(Path.cwd().resolve()).as_posix()
        except ValueError:
            return p.resolve().as_posix()

    def load_entry_model(self, entry: dict[str, Any]) -> dict[str, Any]:
        """按版本条目加载模型：先 sha256 复核 blob 再反序列化（§6.3-5）。

        Returns:
            ``{"ok": True, "model": ...}`` 或
            ``{"ok": False, "reason": "blob_missing"|"blob_sha256_mismatch"|
            "unpickle_failed", "detail": ...}``——拒用不崩溃。
        """
        blob_path = entry.get("blob_path")
        expect = entry.get("model_blob_sha256")
        if not blob_path or not expect:
            return {"ok": False, "reason": "blob_missing",
                    "detail": "条目缺 blob_path/model_blob_sha256"}
        blob = Path(str(blob_path))
        if not blob.exists() and str(expect):
            # cwd 漂移兜底：blob 内容寻址可由 store_dir 重建定位
            candidate = self.store_dir / f"{expect}{_BLOB_EXT}"
            if candidate.exists():
                blob = candidate
        if not blob.exists():
            # 展示路径相对 cwd；展示与解析同源（_display_path 生成）
            return {"ok": False, "reason": "blob_missing",
                    "detail": f"blob 不存在: {blob_path}"}
        try:
            actual = sha256_file(blob)
        except OSError as exc:
            return {"ok": False, "reason": "blob_missing",
                    "detail": f"blob 不可读: {exc}"}
        if actual != str(expect):
            return {"ok": False, "reason": "blob_sha256_mismatch",
                    "detail": f"期望 {expect} 实测 {actual}"}
        try:
            with open(blob, "rb") as f:
                model = pickle.load(f)
        except Exception as exc:
            return {"ok": False, "reason": "unpickle_failed",
                    "detail": f"{exc}"}
        return {"ok": True, "model": model}

    # ── 查询面 ───────────────────────────────────────────────────────────────

    def query(
        self,
        *,
        template_family: str | None = None,
        channel: str | None = None,
        status: str | None = None,
        stale: bool | None = None,
    ) -> list[dict[str, Any]]:
        """展平版本行（键字段+版本字段），四维过滤；None=不过滤。"""
        doc = self.load()
        rows: list[dict[str, Any]] = []
        for entry in self._entries(doc):
            key = entry.get("key") or {}
            if template_family is not None and \
                    str(key.get("template_family")) != str(template_family):
                continue
            if channel is not None and str(key.get("channel")) != str(channel):
                continue
            for ver in entry.get("versions") or []:
                if status is not None and \
                        str(ver.get("status")) != str(status):
                    continue
                if stale is not None and bool(ver.get("stale")) is not stale:
                    continue
                row = {f: key.get(f) for f in KEY_FIELDS}
                row.update(dict(ver))
                rows.append(row)
        rows.sort(key=lambda r: (
            key_sort_id(r), int(r.get("version") or 0)))
        return rows

    def champion(
        self, key: dict[str, Any],
    ) -> dict[str, Any]:
        """同键非 stale champion 查找（读取面守卫，spec §6.2-2①）。

        Returns:
            ``{"ok": True, "entry": {...}}`` 或
            ``{"ok": False, "reason": "no_champion"|"stale",
            "stale_reason": ...}``——stale champion 拒用并带锚指针。
        """
        doc = self.load()
        entry = self._find_entry(doc, key)
        if entry is None:
            return {"ok": False, "reason": "no_champion",
                    "detail": "键无任何版本"}
        for ver in entry.get("versions") or []:
            if str(ver.get("status")) != STATUS_CHAMPION:
                continue
            if bool(ver.get("stale")):
                return {"ok": False, "reason": "stale",
                        "stale_reason": ver.get("stale_reason"),
                        "entry": dict(ver)}
            return {"ok": True, "entry": dict(ver)}
        return {"ok": False, "reason": "no_champion",
                "detail": "键无 champion 状态版本"}

    # ── 变更面（全部持锁）───────────────────────────────────────────────────

    def upsert(
        self,
        *,
        key: dict[str, Any],
        model: Any = None,
        model_bytes: bytes | None = None,
        heldout: dict[str, Any],
        hyperparams: dict[str, Any] | None = None,
        trained_run_ids: list[str] | None = None,
        render_commit: str | None = None,
        promote: bool = False,
        version: int | None = None,
        created_at: str | None = None,
    ) -> dict[str, Any]:
        """注册新版本或原位重登记（幂等，spec §6.3-4）。

        - ``heldout`` 强制字段（无 heldout 不入注册表——防"不可评"模型进
          champion 位）；结构 ``{metric, value, n_points}``；
        - ``version=None``：键内 max+1 分配；同键最新版本 blob/超参/heldout
          全同 → 幂等返回既有版本不膨胀；
        - ``version=显式``：存在则原位替换（不膨胀），不存在则插入；
        - champion 策略：键无 champion → 新版本即 champion；已有 champion →
          新版本为 challenger，``promote=True`` 才接管（旧 champion 降
          challenger，MLflow 挑战语义）。
        """
        _require_heldout(heldout)
        if model is None and model_bytes is None:
            raise ValueError("model / model_bytes 至少给一个")
        data = bytes(model_bytes) if model_bytes is not None \
            else pickle.dumps(model)
        commit = render_commit if render_commit is not None else current_git_sha()
        kid = key_sort_id(key)

        with self._locked():
            doc = self.load()
            entry = self._find_entry(doc, key)
            if entry is None:
                entry = {"key": {f: key[f] for f in KEY_FIELDS},
                         "versions": []}
                self._entries(doc).append(entry)
                self._entries(doc).sort(key=lambda e: key_sort_id(e.get("key") or {}))
            versions: list[dict[str, Any]] = entry.setdefault("versions", [])

            sha, blob_display = self._store_blob(data)

            if version is None:
                latest = versions[-1] if versions else None
                if latest is not None and self._same_content(
                        latest, sha, hyperparams, heldout):
                    return {"ok": True, "deduped": True, "entry": dict(latest),
                            "version": latest.get("version")}
                next_ver = max((int(v.get("version") or 0) for v in versions),
                               default=0) + 1
                status = self._assign_status(versions, promote=promote)
                record = self._make_record(
                    next_ver, sha, blob_display, heldout, hyperparams,
                    trained_run_ids, commit, created_at, status)
                versions.append(record)
            else:
                ver_int = int(version)
                status = self._assign_status(versions, promote=promote)
                record = self._make_record(
                    ver_int, sha, blob_display, heldout, hyperparams,
                    trained_run_ids, commit, created_at, status)
                replaced = False
                for i, v in enumerate(versions):
                    if int(v.get("version") or 0) == ver_int:
                        versions[i] = record
                        replaced = True
                        break
                if not replaced:
                    versions.append(record)
                versions.sort(key=lambda v: int(v.get("version") or 0))

            versions.sort(key=lambda v: int(v.get("version") or 0))
            self._save(doc)
            return {"ok": True, "deduped": False, "entry": dict(record),
                    "version": record["version"], "key_id": kid}

    @staticmethod
    def _same_content(
        record: dict[str, Any], sha: str,
        hyperparams: dict[str, Any] | None, heldout: dict[str, Any],
    ) -> bool:
        return (
            str(record.get("model_blob_sha256")) == sha
            and (record.get("hyperparams") or {}) == dict(hyperparams or {})
            and (record.get("heldout") or {}) == dict(heldout)
        )

    @staticmethod
    def _assign_status(
        versions: list[dict[str, Any]], *, promote: bool,
    ) -> str:
        # 键内无任何 champion（含 stale champion——漂移后重训不静默顶替，
        # 须显式 promote 复验通过语义，spec §6.2-2②）→ 新版本自动 champion
        has_champion = any(
            str(v.get("status")) == STATUS_CHAMPION for v in versions)
        if promote or not has_champion:
            # 接管/首版：旧 champion 降 challenger
            for v in versions:
                if str(v.get("status")) == STATUS_CHAMPION:
                    v["status"] = STATUS_CHALLENGER
            return STATUS_CHAMPION
        return STATUS_CHALLENGER

    @staticmethod
    def _make_record(
        version: int,
        sha: str,
        blob_display: str,
        heldout: dict[str, Any],
        hyperparams: dict[str, Any] | None,
        trained_run_ids: list[str] | None,
        render_commit: str | None,
        created_at: str | None,
        status: str,
    ) -> dict[str, Any]:
        return {
            "version": int(version),
            "model_blob_sha256": sha,
            "blob_path": blob_display,
            "trained_run_ids": [str(r) for r in (trained_run_ids or [])],
            "render_commit": render_commit,
            "hyperparams": dict(hyperparams or {}),
            "heldout": dict(heldout),
            "created_at": created_at or utc_now_iso(),
            "status": status,
            "stale": False,
            "stale_reason": None,
        }

    def mark_family_stale(
        self, template_family: str, stale_reason: str,
    ) -> dict[str, Any]:
        """族级漂移失效：同 template_family 全版本标 stale（§6.2-2②）。

        幂等：重复标记更新 stale_reason 不膨胀；retired 版本同样标记
        （spec 原文"全版本"；retired 本就不被消费，标记无副作用）。
        """
        reason = str(stale_reason)
        with self._locked():
            doc = self.load()
            n_marked = 0
            for entry in self._entries(doc):
                key = entry.get("key") or {}
                if str(key.get("template_family")) != str(template_family):
                    continue
                for ver in entry.get("versions") or []:
                    ver["stale"] = True
                    ver["stale_reason"] = reason
                    n_marked += 1
            if n_marked:
                self._save(doc)
            return {"ok": True, "n_marked": n_marked, "stale_reason": reason}

    def set_version_status(
        self, key: dict[str, Any], version: int, status: str,
        *, clear_stale: bool = False,
    ) -> dict[str, Any]:
        """版本状态机（promote/retire 单源；promote 清 stale=复验通过语义）。"""
        if status not in (STATUS_CHAMPION, STATUS_CHALLENGER, STATUS_RETIRED):
            raise ValueError(f"未知状态: {status}")
        with self._locked():
            doc = self.load()
            entry = self._find_entry(doc, key)
            if entry is None:
                return {"ok": False, "reason": "no_entry"}
            target = None
            for ver in entry.get("versions") or []:
                if int(ver.get("version") or 0) == int(version):
                    target = ver
                elif status == STATUS_CHAMPION and \
                        str(ver.get("status")) == STATUS_CHAMPION:
                    ver["status"] = STATUS_CHALLENGER
            if target is None:
                return {"ok": False, "reason": "no_version",
                        "detail": f"version {version} 不存在"}
            target["status"] = status
            if clear_stale:
                target["stale"] = False
                target["stale_reason"] = None
            self._save(doc)
            return {"ok": True, "entry": dict(target)}


def _require_heldout(heldout: Any) -> None:
    """heldout 强制字段校验（无 heldout 不入注册表，spec §6.2-3）。"""
    if not isinstance(heldout, dict):
        raise ValueError("heldout 强制字段缺失（无 heldout 不入注册表）")
    metric = heldout.get("metric")
    value = heldout.get("value")
    n_points = heldout.get("n_points")
    if not isinstance(metric, str) or not metric:
        raise ValueError("heldout.metric 须为非空字符串")
    if isinstance(value, bool) or not isinstance(value, (int, float)) \
            or value != value or value in (float("inf"), float("-inf")):
        raise ValueError("heldout.value 须为有限数值")
    if isinstance(n_points, bool) or not isinstance(n_points, int) \
            or n_points < 1:
        raise ValueError("heldout.n_points 须为正整数")


# ─── heldout 确定性内核（铁律 7：数字只出自确定性模型）────────────────────────


def heldout_linf(
    surrogate_kind: str,
    surrogate_config: dict[str, Any] | None,
    samples: list[dict[str, Any]],
    objectives: list[Any],
    *,
    frac: float = 0.25,
    min_train: int = 4,
) -> dict[str, Any] | None:
    """留出集 linf 评估（heldout 强制字段的确定性内核）。

    - 确定性切分：按 params canonical json 排序，尾部 ``ceil(n·frac)``
      为 heldout（与采集序/时序无关，同输入同切分）；
    - 训练子集重拟合同 kind 代理 → heldout 逐点预测 metrics →
      SpecEvaluator 转 cost → linf=max|pred−true|；
    - 样本不足（训练子集 < min_train 或无一可用指标）→ 返回 None
      （调用方不得伪造数值——无 heldout 不入注册表）。
    """
    from rfauto.core.objectives import SpecEvaluator
    from rfauto.optimization.surrogate import surrogate_registry

    n = len(samples)
    if n <= min_train:
        return None
    n_hold = max(1, round(n * float(frac)))
    if n - n_hold < min_train:
        return None

    def _sort_key(s: dict[str, Any]) -> str:
        return json.dumps(s.get("params") or {}, sort_keys=True,
                          ensure_ascii=False)

    ordered = sorted(samples, key=_sort_key)
    hold, train = ordered[-n_hold:], ordered[:-n_hold]

    cfg = deepcopy(surrogate_config or {})
    cfg["bounds"] = {k: tuple(v) for k, v in (cfg.get("bounds") or {}).items()}
    model = surrogate_registry.create(surrogate_kind, config=cfg)
    model.fit([
        {"params": dict(s["params"]), "metrics": dict(s.get("metrics") or {})}
        for s in train])
    if not getattr(model, "fitted", False):
        return None

    errs: list[float] = []
    for s in hold:
        try:
            pred = model.predict(dict(s["params"]))
            pred_cost = float(
                SpecEvaluator.evaluate_objectives(pred, objectives))
        except Exception:
            return None  # 预测不可得=heldout 不可评，如实 None 不凑数
        errs.append(abs(pred_cost - float(s["cost"])))
    if not errs:
        return None
    return {"metric": "linf", "value": float(max(errs)),
            "n_points": len(hold)}


def upsert_from_surrogate_loop(
    *,
    model: Any,
    samples: list[dict[str, Any]],
    bounds: dict[str, Any],
    objectives: list[Any],
    surrogate_kind: str,
    surrogate_config: dict[str, Any] | None,
    meta: dict[str, Any],
) -> dict[str, Any]:
    """训练收尾 upsert（run_surrogate_loop 尾钩消费；heldout 强制）。

    meta 键：template_family / channel 必填；trained_run_ids、preprocessing、
    registry_path、store_dir、render_commit 可选。任何失败以
    ``{"ok": False, "reason": ...}`` 返回（调用方 best-effort #105）。
    """
    try:
        family = str(meta.get("template_family") or "")
        channel = str(meta.get("channel") or "")
        if not family or not channel:
            return {"ok": False,
                    "reason": "registry_meta 缺 template_family/channel"}
        heldout = heldout_linf(
            surrogate_kind, surrogate_config, samples, objectives)
        if heldout is None:
            return {"ok": False, "reason": "insufficient_samples_for_heldout",
                    "n_samples": len(samples)}
        feature_names = [str(k) for k in bounds]
        fingerprint = feature_set_fingerprint(
            feature_names, meta.get("preprocessing"))
        key = canonical_key(family, channel, fingerprint)
        hyper = {"kind": surrogate_kind, **{
            k: v for k, v in (surrogate_config or {}).items()
            if isinstance(v, (int, float, str, bool)) or v is None}}
        reg = ModelRegistry(
            registry_path=meta.get("registry_path"),
            store_dir=meta.get("store_dir"))
        res = reg.upsert(
            key=key,
            model=model,
            heldout=heldout,
            hyperparams=hyper,
            trained_run_ids=meta.get("trained_run_ids"),
            render_commit=meta.get("render_commit"),
        )
        res["heldout"] = heldout
        res["key"] = key
        return res
    except Exception as exc:  # 注册失败不阻塞战役（#105）
        return {"ok": False, "reason": "registry_upsert_failed",
                "detail": f"{exc}"}

files.src/rfauto/optimization/surrogate/base.p:
"""代理模型接口（v0 契约层，docs/surrogate_calibration_design.md §1）。

设计目标（用户拍板的接口化要求）：任何外部正向代理模型——无论是内置的
空间映射/GP，还是第三方 NN（如法动 SOTA）、他人自定义模型——都通过实现
SurrogateModel 并注册进 SurrogateRegistry 接入 tune/校准链路，框架其余
部分只依赖基类契约。

最小契约：
    model = MySurrogate(config=...)
    info = model.fit(samples)          # samples: [{"params": {...}, "metrics": {...}}]
    metrics = model.predict(params)    # 返回与 objectives 指标同名的 dict
    sigma = model.uncertainty(params)  # 可选；返回 None 表示无不确定性估计

用法（第三方）：
    from rfauto.optimization.surrogate import SurrogateModel, surrogate_registry

    @surrogate_registry.register("my_nn")
    class MySurrogate(SurrogateModel):
        KIND = "my_nn"
        def fit(self, samples): ...
        def predict(self, params): ...
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Callable
from typing import Any

from rfauto.infra.registry_kit import RegistryKit

__all__ = ["SurrogateModel", "SurrogateRegistry", "surrogate_registry"]


class SurrogateModel(ABC):
    """正向代理模型基类（粗筛用，不承担最终结论——精算永远走真机通道）。

    契约说明：
    - params/metrics 均为"参数名 → 数值"的平铺 dict，与配方
      optimization.params / SpecEvaluator 指标键一致；
    - fit 的 samples 里 metrics 缺失或非数值的条目应被实现方忽略
      （对应真机失败 trial）；
    - predict 必须是纯函数语义（同参数同输出），可复现性红线（C4）。
    """

    #: 代理种类标识（注册键；子类必须覆盖）
    KIND: str = ""

    def __init__(self, config: dict[str, Any] | None = None) -> None:
        self.config: dict[str, Any] = dict(config or {})
        self._fitted = False

    @abstractmethod
    def fit(self, samples: list[dict[str, Any]]) -> dict[str, Any]:
        """用采样数据拟合代理，返回拟合信息 dict（至少含 n_samples）。"""

    @abstractmethod
    def predict(self, params: dict[str, float]) -> dict[str, Any]:
        """预测给定参数的指标（metrics 同构 dict）。"""

    def uncertainty(self, params: dict[str, float]) -> dict[str, float] | None:
        """预测不确定性（如 ±σ）；默认无（返回 None）。"""

    def predict_with_std(
        self, params: dict[str, float],
    ) -> dict[str, tuple[float, float | None]]:
        """预测 + 不确定度合并面（DP-16 U3：mean±σ，variance 透出）。

        返回 {metric: (mean, std|None)}；模型未实现 uncertainty（基类
        默认 None，如 poly_ridge/gbdt）时 std=None——调用方对 None 如实
        标注"无原生逐点不确定度"，不得伪造 0（#122 诚实纪律）。
        """
        mean = self.predict(params)
        std = self.uncertainty(params)
        if std is None:
            return {k: (float(v), None) for k, v in mean.items()}
        return {k: (float(v), (float(std[k]) if k in std else None))
                for k, v in mean.items()}

    @property
    def fitted(self) -> bool:
        return self._fitted

    def _mark_fitted(self, n_samples: int) -> dict[str, Any]:
        self._fitted = True
        return {"kind": self.KIND, "n_samples": n_samples}


class SurrogateRegistry(RegistryKit[Callable[..., SurrogateModel]]):
    """代理模型注册表（基类+注册表模式，同 EMSolverRegistry）。

    T6 试点（R1 审计 §面5/T6）：dict+装饰器样板由 infra.registry_kit.
    RegistryKit 承载——历史语义逐项保真：重名**静默覆盖**
    （allow_overwrite=True）、缺名 KeyError 文案逐字节不变、
    available()=keys() 别名。
    """

    def __init__(self) -> None:
        super().__init__(
            label="代理类型",
            allow_overwrite=True,
            missing_fmt="未注册的{label}: {key}，可用: {keys}")

    def register(
        self, kind: str, factory: Callable[..., SurrogateModel] | None = None,
    ) -> Callable:
        """注册代理工厂（可作装饰器：@registry.register("my_nn")）。"""
        if factory is not None:
            return super().register(kind, factory)
        return super().register(kind)

    def available(self) -> list[str]:
        return self.keys()


surrogate_registry = SurrogateRegistry()

